function showModal(title,html){if(activeAlert)return false;modalGeneration++;routeController?.abort();routeController=null;installHelp.controller?.abort();installHelp.controller=null;const modal=$('#modal');if(!modal.open)showModal.returnFocus=document.activeElement;$('#modalContent').innerHTML=`<div class="dialog-head"><h2 id="modalTitle" tabindex="-1">${esc(title)}</h2><button class="icon-button" id="closeModal" aria-label="Fermer">${icon('close')}</button></div><div class="dialog-body" id="modalBody">${html}</div>`;$('#closeModal').onclick=()=>closeModal();if(!modal.open)modal.showModal();modal.scrollTop=0;$('#modalTitle').focus();return true}
function closeModal(restoreFocus=true){modalGeneration++;const modal=$('#modal'),wasOpen=modal.open;if(wasOpen)modal.close();routeController?.abort();routeController=null;installHelp.controller?.abort();installHelp.controller=null;if(wasOpen&&restoreFocus){const target=showModal.returnFocus?.isConnected?showModal.returnFocus:$('#content h2');if(target){if(target.tagName==='H2')target.tabIndex=-1;target.focus()}}}
window.closeTopOverlay=()=>{if(!$('#alertOverlay').hidden){hideAlert();return true}if($('#modal').open){closeModal();return true}return false};
$('#modal').addEventListener('close',()=>{routeController?.abort();routeController=null});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
function help(){showModal('Le bon arrêt, simplement.',`<p><b>1. Choisissez votre destination.</b><br>Vérifiez le nom et la ville. Ajoutez votre ligne et son sens si les données sont disponibles.</p><p><b>2. Testez votre alerte, puis démarrez.</b><br>Le GPS déclenche un rappel d’approche, puis une alerte près de votre destination. La distance est mesurée à vol d’oiseau.</p><p><b>3. Descendez et terminez le trajet.</b><br>Le suivi GPS s’arrête. Vous pouvez aussi l’arrêter à tout moment.</p><div class="notice">${icon('info')}<div><b>Une aide, pas une garantie.</b> Les tunnels, le mode silencieux, une batterie épuisée, une fermeture forcée ou une mauvaise position peuvent empêcher les alertes. Aucune heure d’arrivée ni information de trafic en temps réel n’est utilisée. Le GPS ne distingue pas des quais ou des stations superposés et ne sait pas si votre véhicule dessert l’arrêt.</div></div><p><b>Web :</b> page visible et écran allumé indispensables. <b>Android :</b> le service natif permet le suivi en arrière-plan ; les réglages du système restent prioritaires.</p><button class="secondary" id="installFromHelp">Utiliser sur mon téléphone</button>`);$('#installFromHelp').onclick=installHelp}
async function installHelp(){
  if(activeAlert)return;
  if(native){showModal('Version Android pilote',`<p>Le suivi commence à votre demande et peut continuer lorsque vous changez d’application ou éteignez l’écran.</p><p><b>Avant votre premier vrai trajet :</b> testez les notifications, puis faites un essai court avec l’écran verrouillé. Le volume, le mode Ne pas déranger et les restrictions de batterie restent prioritaires.</p><p>Version pilote 1.2.0. Les essais sur émulateur ne remplacent pas la validation sur votre téléphone et votre réseau de transport.</p>`);return;}
  if(!showModal('Sur votre téléphone',`<p><b>Android :</b> l’application permet le suivi en arrière-plan.</p><p><b>Web et iPhone :</b> gardez cette page visible et l’écran allumé.</p><p role="status"><span class="spinner" aria-hidden="true"></span> Vérification du téléchargement Android…</p>`))return;
  const token=modalGeneration,epoch=generation,ac=new AbortController();installHelp.controller=ac;let available=false,failed=false,timer;
  try{const result=await Promise.race([fetch('./release.json',{cache:'no-store',signal:ac.signal}).then(r=>{if(!r.ok)throw new Error('Téléchargement non vérifié');return r.json()}),new Promise((_,reject)=>{timer=setTimeout(()=>{ac.abort();reject(new Error('Délai dépassé'))},6000)})]);available=result?.androidAvailable===true;}catch{failed=true;}finally{clearTimeout(timer);if(installHelp.controller===ac)installHelp.controller=null;}
  if(token!==modalGeneration||epoch!==generation||activeAlert||!$('#modal').open)return;
  showModal('Sur votre téléphone',`<span class="small-badge">ANDROID · SUIVI EN ARRIÈRE-PLAN</span><p>Pour verrouiller votre téléphone ou utiliser une autre app, téléchargez l’application Android.</p>${available?'<a class="primary" href="./prochain-arret-android.apk" download>Télécharger l’app Android (APK)</a><p class="note">Version pilote 1.2.0, hors Play Store. Pour remplacer un ancien pilote, désinstallez-le d’abord : ses données locales seront effacées. Android peut demander d’autoriser cette installation. Prenez uniquement le fichier de cette page, puis testez une alerte écran verrouillé.</p>':`<div class="notice">${failed?'Le téléchargement n’a pas pu être vérifié. Vérifiez votre connexion et réessayez.':'Le téléchargement Android n’est pas disponible pour le moment.'}</div><button class="secondary" id="retryInstall">Réessayer</button>`}<div class="fine-divider"></div><p><b>iPhone et version web :</b> ouvrez cette page dans Safari ou Chrome. Vous pouvez l’ajouter à l’écran d’accueil ; gardez-la visible et l’écran allumé pendant le trajet.</p>${deferredInstall?'<button class="secondary" id="installPwa">Ajouter la version web</button>':''}<p class="note">L’installation web ne donne pas accès au GPS en arrière-plan.</p>`);
  $('#retryInstall')?.addEventListener('click',installHelp);
  $('#installPwa')?.addEventListener('click',async()=>{const prompt=deferredInstall;if(!prompt)return;try{await prompt.prompt();deferredInstall=null;closeModal()}catch{toast('L’ajout à l’écran d’accueil n’a pas abouti. Réessayez depuis le menu du navigateur.')}});
}
function privacy(){showModal('Votre trajet reste le vôtre.',`<p><b>Votre position ne nous est pas envoyée.</b> Le calcul des alertes s’effectue sur votre appareil. Aucun compte dans l’app, aucune publicité, aucun outil de mesure d’audience.</p><p><b>Pour rechercher un arrêt :</b> le texte saisi est transmis à Photon (komoot). La recherche autour de vous et celle des lignes transmettent des coordonnées aux serveurs Overpass (overpass-api.de et, en cas de panne, Private.coffee), qui utilisent les données OpenStreetMap. Ces services reçoivent aussi les informations habituelles d’une connexion, dont votre adresse IP.</p><p><b>Sur cet appareil :</b> les favoris, destinations récentes, réglages et le trajet actif sont conservés localement. Aucun historique complet de vos déplacements n’est enregistré. Vous pouvez tout effacer dans Réglages.</p><p><b>Hors connexion :</b> après le premier chargement, l’interface web peut être mise en cache. Les favoris et le GPS restent utilisables lorsque l’application peut obtenir une position. La recherche et le chargement des lignes nécessitent Internet. La version Android embarque l’interface.</p><p>Les profils adaptent les rayons au transport ; ils ne garantissent pas la couverture d’un opérateur. Les données de transport viennent d’<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap (ODbL)</a> et peuvent être incomplètes ou obsolètes.</p><p class="note">Cette page est publique, sans connexion. Les journaux techniques de son hébergeur sont distincts du stockage local de l’app.</p>`)}
function networkStatus(){const c=$('#connection');const offline=!navigator.onLine;c.classList.toggle('offline',offline);c.innerHTML=`<span class="status-dot"></span> ${offline?'Hors connexion · recherche indisponible':trip?(trip.demo?'Simulation en cours':engine?.health()==='good'?'Trajet en cours':'Vérification du signal'):'Prêt pour le prochain trajet'}`}
$$('.tab').forEach(b=>b.onclick=()=>switchPage(b.dataset.page));$('#helpTop').onclick=help;$('#helpFooter').onclick=help;$('#platformBadge').onclick=installHelp;$('#privacy').onclick=privacy;
window.addEventListener('online',networkStatus);window.addEventListener('offline',networkStatus);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});
window.addEventListener('beforeunload',e=>{if(trip&&!trip.demo&&!native){e.preventDefault();e.returnValue=''}});
document.addEventListener('visibilitychange',()=>{if(!trip||trip.demo||native)return;if(!ensureOwnership())return;if(document.hidden){hush();showNotification('Gardez Prochain arrêt visible','Le suivi web peut s’interrompre lorsque cette page est masquée.','pa-hidden')}else{requestWake();tick()}});
document.addEventListener('keydown',e=>{if($('#alertOverlay').hidden)return;if(e.key==='Escape'){e.preventDefault();hideAlert()}if(e.key==='Tab'){const list=[...$('#alertOverlay').querySelectorAll('button')];if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus()}}});
window.onAndroidError=msg=>{toast(msg);if(trip&&!trip.demo){stopTrip();page='configure';render()}};
if(native){try{const s=JSON.parse(window.Android.state());if(s.running&&s.config&&validTrip(s.config)){trip=s.config;engine=new TripEngine(trip,s);page='tracking';poll=setInterval(pollNative,1000)}else if(s.completed){recovered=null;save('trip',null)}else if(s.config&&validTrip(s.config)&&!s.arrived){recovered=s.config}}catch{}}
let updatePending=false,waitingWorker=null;
function offerUpdate(worker){if(!worker)return;waitingWorker=worker;if(!$('#applyUpdate')){$('.app-footer').insertAdjacentHTML('beforeend','<button id="applyUpdate">Nouvelle version disponible</button>');$('#applyUpdate').onclick=()=>{if(trip||starting){toast('Terminez le trajet avant de mettre à jour.');return}if(waitingWorker){updatePending=true;$('#applyUpdate').disabled=true;$('#applyUpdate').textContent='Mise à jour…';waitingWorker.postMessage({type:'ACTIVATE_UPDATE'});setTimeout(()=>{if(updatePending){updatePending=false;$('#applyUpdate')&&( $('#applyUpdate').disabled=false);toast('Fermez les autres onglets de l’app, puis réessayez la mise à jour.')}},8000)}}}}
window.addEventListener('storage',e=>{if(e.key==='pa:reset'){clearSearchCache();hideAlert();stopTrip();favorites=[];recent=[];prefs=defaults();recovered=null;closeModal();page='home';render();toast('Données effacées depuis un autre onglet.')}else if(e.key==='pa:owner'&&trip&&!trip.demo&&!native)ensureOwnership()});
window.addEventListener('pagehide',()=>{if(!native)ownership.release()});
window.addEventListener('pageshow',e=>{if(e.persisted&&trip&&!native&&!trip.demo){stopTrackingResources();recovered=trip;trip=null;engine=null;page='home';render();toast('Le suivi a été interrompu. Relancez le trajet.')}});
if(!native&&'serviceWorker'in navigator){
  navigator.serviceWorker.register('./sw.js').then(reg=>{offerUpdate(reg.waiting);reg.addEventListener?.('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)offerUpdate(reg.waiting||worker)})})}).catch(()=>{});
  navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='OPEN_TRIP')switchPage('home');if(e.data?.type==='UPDATE_BLOCKED'){updatePending=false;if($('#applyUpdate'))$('#applyUpdate').disabled=false;toast('Fermez les autres onglets de l’app avant la mise à jour.')}});
  navigator.serviceWorker.addEventListener('controllerchange',()=>{if(updatePending&&!trip&&!starting)location.reload()});
}
render();if(native&&trip)pollNative();

if(!trip&&new URL(location.href).searchParams.has('demo')){
  showModal('Essayez en 30 secondes.', '<p>Un trajet fictif, deux alertes. Aucun compte ni accès à votre position : touchez le bouton, puis laissez la démo avancer.</p><button class="primary" id="quickDemo">Lancer la démo</button><p class="note">Activez le son de votre appareil pour entendre les alertes.</p>');
  $('#quickDemo').onclick=()=>{closeModal();startDemo()};
}
